async page => {
  const names=[];
  const failures=[];
  const errors=[];
  page.on('pageerror', error=>errors.push(error.message));
  const check=(ok,name)=>{names.push(name);if(!ok)failures.push(name);};
  const act=action=>page.locator(`[data-action="${action}"]`).click();
  const text=()=>page.locator('#content').innerText();
  const scenario=value=>page.locator('#scenario').selectOption(value);
  await page.reload();
  await page.locator('details.lab summary').click();
  check(await page.locator('input[name="strategy"]').count()===2 && await page.locator('input[value="merge"]').isChecked(),'只有Merge與Rebase兩個主選項，預設Merge');
  check(!(await text()).includes('查看變更') && !(await text()).includes('更新這個工作') && !(await text()).includes('建立隔離工作'),'移除查看、同步與建立入口');
  check((await text()).includes('~/worktrees/atlas/fix-login'),'來源worktree身分與路徑可見');
  check((await text()).includes('M 把兩邊接起來') && (await text()).includes('1、2 重播成 1′、2′'),'用同一提交例子對照Merge與Rebase');
  await page.locator('#target').selectOption('release');
  await page.locator('input[value="rebase"]').check();
  check(await page.getByRole('button',{name:'預覽 Rebase 收尾'}).count()===1 && (await text()).includes('提交歷史會改寫'),'Rebase名稱直接對應按鈕與改寫提醒');
  await act('preview');
  check((await text()).includes('Rebase 這個工作，再快轉目標分支') && (await text()).includes('讓 release 快轉'),'Rebase之後另行快轉目標完成收尾');
  await act('form');
  check(await page.locator('#target').inputValue()==='release' && await page.locator('input[value="rebase"]').isChecked(),'返回保留目標及策略');
  await act('preview');await act('execute');
  check((await text()).includes('目前開啟：release') && (await text()).includes('資料夾與分支都保留'),'完成後位置與預設保留明確');
  await scenario('dirty');
  check((await text()).includes('全部 3 個變更檔案') && (await text()).includes('已暫存、未暫存與新增'),'無查看入口仍揭露完整提交範圍');
  await act('preview');
  check((await text()).includes('先提交全部 3 個變更檔案'),'確認頁保留自動提交步驟');
  await scenario('ff');await page.locator('input[value="rebase"]').check();await act('preview');
  check((await text()).includes('不必重播提交') && !(await text()).includes('提交歷史會改寫'),'快轉例外不誤稱必定改寫');
  await scenario('ready');await page.locator('#advanced summary').click();await page.locator('#squash').check();
  check((await text()).includes('先合成 S，再用 M 接起來') && (await text()).includes('仍可能新增 2 個提交'),'Squash加Merge圖與提交數提醒一致');
  await page.locator('#remove').check();await page.locator('input[value="rebase"]').check();await act('preview');
  check((await text()).includes('移除資料夾') && (await text()).includes('~/worktrees/atlas/fix-login') && (await text()).includes('歷史會改寫'),'清理精確路徑與改寫後果不可隱藏');
  await scenario('merge-history');
  check(await page.locator('input[value="rebase"]').isDisabled() && (await text()).includes('本工具目前'),'合併提交限制明示為本工具限制');
  await page.locator('#advanced summary').click();await page.locator('#squash').check();
  check(!(await page.locator('input[value="rebase"]').isDisabled()),'選Squash後可使用Rebase收尾');
  await scenario('conflict');await act('preview');
  check(await page.locator('[data-action="execute"]').count()===0 && (await text()).includes('src/Login.tsx'),'衝突停在預檢並顯示處理方向');
  await scenario('terminal');await act('preview');await act('resolved');
  check(await page.locator('[data-action="execute"]').count()===1,'終端阻擋有重新檢查入口');
  await scenario('unknown');await act('preview');await act('execute');
  check(await page.locator('#content button').count()===0 && (await text()).includes('請勿重送'),'結果不明保留現場且不能重送');
  await scenario('ready');await page.locator('details.lab summary').click();
  await page.setViewportSize({width:1000,height:1100});
  await page.screenshot({path:'/tmp/worktree-finish-simple-wide.png',fullPage:true});
  await page.locator('details.lab summary').click();await page.locator('#width').selectOption('narrow');await page.locator('details.lab summary').click();
  await page.setViewportSize({width:400,height:1000});
  check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'窄側欄無水平溢出');
  await page.screenshot({path:'/tmp/worktree-finish-simple-narrow.png',fullPage:true});
  check(errors.length===0,'無JavaScript錯誤');
  return {checked:names.length,failures,errors,names};
}
